command:
if (!actor) {
  ui.notifications.error("You must select an actor to update.");
  return;
}

const TITLE = "Add XP";
const FIELDNAME = actor.type === "trainer" ? "system.level.xpPool" : "system.level.pendingExp";
const FIELDLABEL = actor.type === "trainer" ? "Add to XP Pool" : "Add to Pending Experience";
const EXISTING = foundry.utils.getProperty(actor, FIELDNAME) ?? 0;

const field = new foundry.data.fields.NumberField({
  label: FIELDLABEL,
  placeholder: 0,
  min: 0
}, {
  name: FIELDNAME.substring(FIELDNAME.lastIndexOf(".") + 1),
  parent: {
    fieldPath: FIELDNAME.substring(0, FIELDNAME.lastIndexOf("."))
  }
});

const name = actor.trainer ? `${actor.trainer.name}'s ${actor.name}` : actor.name;

const content = `<div><h4>${name}</h4><img src="${actor.img}" alt="${name}" style="max-width: 100px; max-height: 100px;"></div><fieldset>${field.toFormGroup({}).outerHTML}</fieldset>`

const { value } = await foundry.applications.api.DialogV2.wait({
  window: { title: TITLE },
  content,
  buttons: [
    {
      action: "apply",
      label: "Apply",
      callback: (event, button) => {
        const form = button.closest("form");
        const formData = new FormData(form);
        return {
          value: Number(formData.get(FIELDNAME)),
        }
      }
    }
  ]
});

if (value !== null && value !== undefined) {
  await actor.update({ [FIELDNAME]: EXISTING + value });
}
